"""References submitted by clients and page requests generated by the Agent."""
from typing import Literal
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field

from assistant_api.services.markdown_attachments import Section


class AttachmentReference(BaseModel):
    """Identify an attachment without accepting paths or claimed ownership."""

    model_config = ConfigDict(extra="forbid")
    kind: Literal["image", "markdown"]
    attachment_id: UUID


class MarkdownPageRequest(BaseModel):
    """Read one part of a Markdown document already attached to this task."""

    model_config = ConfigDict(extra="forbid")
    attachment_id: UUID
    section: Section
    position: int = Field(default=0, ge=0)
